/**
 * Plugin Name: InstaTech page creator: Battery Replacement
 * Description: One-shot. Creates /mobile-repair-services/battery-replacement/ once (approved by the owner on 21 Oct 2026) and sets its
 *              Rank Math title, description and focus keyword. Does nothing once the page exists. Generated by
 *              instatech/tools/build_service_page.py. Safe to leave in place; replace with an empty file to retire it.
 */

defined( 'ABSPATH' ) || exit;

add_action(
	'init',
	function () {
		if ( get_option( 'instatech_page_created_battery-replacement' ) ) {
			return;
		}
		if ( get_page_by_path( 'mobile-repair-services/battery-replacement', OBJECT, 'page' ) ) {
			update_option( 'instatech_page_created_battery-replacement', 'exists', false );
			return;
		}
		// add_option fails if the key exists, so only one request can claim the creation.
		if ( ! add_option( 'instatech_page_creating_battery-replacement', time(), '', false ) ) {
			return;
